import React, { useEffect, useMemo, useState } from "react";
import "./battle.css";
import { cards } from "../data/cards";

// 盤面シンボル合計（軽減計算用）
function getAvailableReductionsFromBoard(playerZones) {
  const sum = { red:0, blue:0, green:0, white:0, yellow:0, purple:0 };
  for (const z of playerZones) {
    if (!z || !z.card) continue;
    const { symbolColor, symbolCount = 1 } = z.card;
    sum[symbolColor] = (sum[symbolColor] || 0) + symbolCount;
  }
  return sum;
}
// 実支払コスト
function calcActualCost(card, availableReductions) {
  let reduce = 0;
  for (const color of Object.keys(card.reduction)) {
    const need = card.reduction[color] || 0;
    const have = availableReductions[color] || 0;
    reduce += Math.min(need, have);
  }
  return Math.max(0, card.cost - reduce);
}
// 現在コア数→レベル情報
function levelFromCores(card, cores) {
  let current = card.levels[0];
  for (const lvInfo of card.levels) {
    if (cores >= lvInfo.core) current = lvInfo;
  }
  return current; // {lv, core, bp}
}

export default function Battle() {
  // デッキ（cards.js から20枚）
  const fullDeck = useMemo(() => {
    const deck = [];
    for (let i = 0; i < 20; i++) {
      const c = cards[i % cards.length];
      deck.push({ ...c, deckIndex: i });
    }
    return deck;
  }, []);

  // HUD
  const [me, setMe]   = useState({ life: 3, reserve: 4, trash: 0 });
  const [op, setOp]   = useState({ life: 5, reserve: 4, trash: 0 });

  // 山札/手札/フィールド
  const [deck, setDeck] = useState([]);
  const [handCards, setHandCards] = useState([]);
  // ゾーン: { card, cores, attacked } / null
  const [playerZones, setPlayerZones]     = useState([null, null, null, null]);
  const [opponentZones] = useState([null, null, null, null]); // 参照用

  const [selectedHandIndex, setSelectedHandIndex] = useState(null);
  const [stepCount, setStepCount] = useState(0);

  // 初期ドロー（4）
  useEffect(() => {
    const d = [...fullDeck];
    const drawn = [];
    for (let i = 0; i < 4; i++) {
      const idx = Math.floor(Math.random() * d.length);
      drawn.push(d.splice(idx, 1)[0]);
    }
    setHandCards(drawn);
    setDeck(d);
  }, [fullDeck]);

  // 次のステップ
  // 1回目: reserve +1（ターン開始扱い→攻撃フラグ解除）
  // 2回目: 山札から1ドロー
  // 3回目: trash→reserve へ全返却して trash=0
  const nextStep = () => {
    const phase = stepCount % 3;

    if (phase === 0) {
      // ターン開始：攻撃フラグ解除
      setPlayerZones(zs => zs.map(z => (z ? { ...z, attacked:false } : z)));
      setMe(m => ({ ...m, reserve: m.reserve + 1 }));
    } else if (phase === 1) {
      if (deck.length > 0) {
        const idx = Math.floor(Math.random() * deck.length);
        const c = deck[idx];
        const nd = [...deck]; nd.splice(idx, 1);
        setDeck(nd);
        setHandCards(h => [...h, c]);
      }
    } else {
      setMe(m => ({ ...m, reserve: m.reserve + m.trash, trash: 0 }));
    }
    setStepCount(c => c + 1);
  };

  // 手札選択
  const onHandClick = (i) => setSelectedHandIndex(prev => (prev === i ? null : i));

  // 召喚：コスト分は TRASH へ、Lv1必要コアはゾーンに乗せる
  const summonToZone = (zoneIdx) => {
    if (selectedHandIndex === null) return;
    if (playerZones[zoneIdx] !== null) return;

    const card = handCards[selectedHandIndex];
    const reductions = getAvailableReductionsFromBoard(playerZones);
    const actualCost = calcActualCost(card, reductions);
    const lv1 = card.levels[0];
    const needCores = lv1.core;

    const totalPay = actualCost + needCores;
    if (me.reserve < totalPay) {
      alert(`コア不足：必要${totalPay}（コスト${actualCost} + Lv${lv1.lv}に必要${needCores}） / 手持ち${me.reserve}`);
      return;
    }

    // 支払い：コスト→TRASH、Lv1コア→ゾーン
    setMe(m => ({
      ...m,
      reserve: m.reserve - totalPay,
      trash:  m.trash + actualCost
    }));
    const newZones = [...playerZones];
    newZones[zoneIdx] = { card, cores: needCores, attacked:false };
    setPlayerZones(newZones);

    // 手札から除去
    const newHand = [...handCards];
    newHand.splice(selectedHandIndex, 1);
    setHandCards(newHand);
    setSelectedHandIndex(null);
  };

  // レベルアップ：追加必要コアを reserve → ゾーンへ
  const levelUp = (zoneIdx) => {
    const z = playerZones[zoneIdx];
    if (!z) return;
    const curr = levelFromCores(z.card, z.cores);
    const levels = z.card.levels;
    const i = levels.findIndex(l => l.lv === curr.lv);
    const next = levels[i + 1];
    if (!next) return;
    const needMore = next.core - z.cores;
    if (needMore <= 0) return;
    if (me.reserve < needMore) {
      alert(`コア不足：Lv${curr.lv}→Lv${next.lv} で +${needMore} 必要 / 手持ち${me.reserve}`);
      return;
    }
    setMe(m => ({ ...m, reserve: m.reserve - needMore }));
    setPlayerZones(zs => {
      const nz = [...zs]; nz[zoneIdx] = { ...z, cores: next.core };
      return nz;
    });
  };

  // レベルダウン：差分コアを ゾーン → reserve に返却
  const levelDown = (zoneIdx) => {
    const z = playerZones[zoneIdx];
    if (!z) return;
    const curr = levelFromCores(z.card, z.cores);
    const levels = z.card.levels;
    const i = levels.findIndex(l => l.lv === curr.lv);
    const prev = levels[i - 1];
    if (!prev) return;
    const refund = z.cores - prev.core;
    setPlayerZones(zs => {
      const nz = [...zs]; nz[zoneIdx] = { ...z, cores: prev.core };
      return nz;
    });
    setMe(m => ({ ...m, reserve: m.reserve + refund }));
  };

  // アタック：未攻撃ならカードのシンボル数だけ相手ライフを減らす
  // （今はブロックなしの単純版。WebSocket導入後ここで宣言→相手の応答で結末分岐予定）
  const attackWith = (zoneIdx) => {
    const z = playerZones[zoneIdx];
    if (!z || z.attacked) return;
    const dmg = Math.max(0, z.card.symbolCount || 1);
    setOp(o => ({ ...o, life: Math.max(0, o.life - dmg) }));
    setPlayerZones(zs => {
      const nz = [...zs]; nz[zoneIdx] = { ...z, attacked:true };
      return nz;
    });
  };

  // ゾーンクリック：空きなら召喚
  const onZoneClick = (zoneIdx) => {
    if (playerZones[zoneIdx] === null) summonToZone(zoneIdx);
  };

  return (
    <div className="board">
      {/* === 自分側（左） === */}
      <section className="side my-side">
        <header className="hud hud-top">
          <span className="hud-item">LIFE <b>{me.life}</b></span>
          <span className="hud-item">RESERVE <b>{me.reserve}</b></span>
          <span className="hud-item">TRASH <b>{me.trash}</b></span>
          <span className="spacer" />
          <button className="btn next-btn" onClick={nextStep}>次のステップ</button>
        </header>

        <div className="field">
          {playerZones.map((z, i) => {
            if (!z) {
              return (
                <div
                  key={i}
                  className={`zone ${selectedHandIndex !== null ? "placeable" : ""}`}
                  onClick={() => onZoneClick(i)}
                >
                  <span>ゾーン{i + 1}</span>
                </div>
              );
            }
            const info = levelFromCores(z.card, z.cores);
            return (
              <div key={i} className="zone filled">
                <img src={z.card.img} alt={z.card.name} className="zone-card" />
                <div className="zone-badge">Lv{info.lv} / BP {info.bp}</div>
                <div className="zone-controls">
                  <button className="btn-small" onClick={() => levelDown(i)}>-</button>
                  <button className="btn-small" onClick={() => levelUp(i)}>+</button>
                  <button
                    className={`btn-small warn ${z.attacked ? "disabled" : ""}`}
                    onClick={() => attackWith(i)}
                    disabled={!!z.attacked}
                    title={z.attacked ? "このターンは攻撃済み" : "アタックする"}
                  >
                    ATK
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        {/* 手札ゾーン */}
        <footer className="hand hand-bottom">
          {handCards.length === 0 ? (
            <span>手札ゾーン</span>
          ) : (
            <div className="hand-cards">
              {handCards.map((card, idx) => (
                <img
                  key={card.deckIndex}
                  src={card.img}
                  alt={card.name}
                  className={`card-img ${selectedHandIndex === idx ? "selected" : ""}`}
                  onClick={() => onHandClick(idx)}
                  draggable={false}
                  title={card.name}
                />
              ))}
            </div>
          )}
        </footer>
      </section>

      {/* 仕切り線 */}
      <div className="divider" />

      {/* === 相手側（右） === */}
      <section className="side op-side">
        <header className="hand hand-top">
          <span>V手札ゾーン</span>
        </header>

        <div className="field">
          {opponentZones.map((z, i) => (
            <div key={i} className={`zone ${z ? "filled" : ""}`}>
              {z ? (
                <>
                  <img src={z.card.img} alt={z.card.name} className="zone-card" />
                  <div className="zone-badge">Lv{levelFromCores(z.card, z.cores).lv}</div>
                </>
              ) : (
                <span>{i + 1}ゾーン</span>
              )}
            </div>
          ))}
        </div>

        <footer className="hud hud-bottom">
          <span className="hud-item red">LIFE <b>{op.life}</b></span>
          <span className="hud-item red">RESERVE <b>{op.reserve}</b></span>
          <span className="hud-item red">TRASH <b>{op.trash}</b></span>
        </footer>
      </section>
    </div>
  );
}
